from __future__ import annotations

from typing import Any


def rank(record: dict[str, Any], hypotheses: dict[str, Any]) -> list[dict[str, Any]]:
    rows = []
    index = 0
    for hypothesis in hypothesis_list(hypotheses):
        score = confidence_of(hypothesis) * 10.0
        score = score + support_value(record, hypothesis) * 0.55
        score = score - contradiction_value(record, hypothesis) * 0.25
        rows = rows + [(-score, index, hypothesis)]
        index = index + 1
    ordered = sorted(rows)
    return [row[2] for row in ordered]


def confidence_of(hypothesis: dict[str, Any]) -> float:
    if 'confidence' in hypothesis:
        return float(hypothesis['confidence'])
    return 0.0


def support_value(record: dict[str, Any], hypothesis: dict[str, Any]) -> float:
    total = 0.0
    for item_id in id_list(hypothesis, 'support'):
        item = find_item(record, str(item_id))
        if len(item) > 0:
            total = total + modality_weight(str(item['modality'])) * cue_quality(str(item['cue']))
    return total


def contradiction_value(record: dict[str, Any], hypothesis: dict[str, Any]) -> float:
    total = 0.0
    for item_id in id_list(hypothesis, 'contradiction'):
        item = find_item(record, str(item_id))
        if len(item) > 0:
            total = total + modality_weight(str(item['modality'])) * cue_quality(str(item['cue']))
    return total


def find_item(record: dict[str, Any], item_id: str) -> dict[str, Any]:
    for item in item_list(record):
        if str(item['id']) == item_id:
            return item
    return {}


def modality_weight(modality: str) -> float:
    if modality == 'audio':
        return 1.3
    if modality == 'visual':
        return 1.0
    if modality == 'text':
        return 0.2
    return 0.5


def cue_quality(cue: str) -> float:
    direct = ('smile', 'Smil', 'laugh', 'Laugh', 'frown', 'Frown', 'furrow', 'Furrow', 'tear', 'Tear', 'cry', 'Cry', 'angry', 'Angry', 'sad', 'Sad', 'happy', 'Happy', 'surpris', 'Surpris', 'fear', 'Fear', 'disgust', 'Disgust', 'frustrat', 'Frustrat', 'neutral expression', 'Neutral expression', 'wide eyes', 'Wide eyes', 'eyes wide', 'Eyes wide', 'cover face', 'Cover face', 'hands on head', 'Hands on head', 'shaking', 'Shaking', 'trembl', 'Trembl')
    appraisal = ('great', 'Great', 'good', 'Good', 'love', 'Love', 'like', 'Like', 'enjoy', 'Enjoy', 'appreciat', 'Appreciat', 'encourag', 'Encourag', 'recommend', 'Recommend', 'awesome', 'Awesome', 'important', 'Important', 'praise', 'Praise', 'bad', 'Bad', 'hate', 'Hate', 'complain', 'Complain', 'wrong', 'Wrong', 'sucks', 'Sucks', 'regret', 'Regret', 'sorry', 'Sorry', 'threat', 'Threat', 'insult', 'Insult', 'problem', 'Problem')
    for token in direct:
        if token in cue:
            return 2.0
    for token in appraisal:
        if token in cue:
            return 2.3
    if 'speech:' in cue or 'Speech:' in cue:
        return 1.3
    if 'prosody:' in cue or 'Prosody:' in cue:
        return 0.35
    if 'gesture' in cue or 'Gesture' in cue or 'lean' in cue or 'Lean' in cue:
        return 0.35
    if 'mouth moving' in cue or 'Mouth moving' in cue or 'looks' in cue or 'Looks' in cue:
        return 0.12
    return 0.05


def item_list(record: dict[str, Any]) -> list[Any]:
    if 'items' in record:
        return list(record['items'])
    return []


def hypothesis_list(hypotheses: dict[str, Any]) -> list[Any]:
    if 'hypotheses' in hypotheses:
        return list(hypotheses['hypotheses'])
    return []


def id_list(hypothesis: dict[str, Any], key: str) -> list[Any]:
    if key in hypothesis:
        return list(hypothesis[key])
    return []
